import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.C0KMm31j.js";const h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_10_table_to_function.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_10_linear_model.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_10_gradient_update.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_10_generalization_interference.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_10_driving_features.png",f=JSON.parse('{"title":"一张 Q 表装不下真实世界：函数逼近怎样让强化学习学会泛化","description":"表格型强化学习有一个隐含前提：每个状态或状态—动作对都能被列出来，并拥有独立的存储位置。这个前提在小型网格世界里成立，到了自动驾驶却立即失效。车速、横向误差、道路曲率和相对距离都是连续量，同一场景还会随交通参与者数量不断改变维度。即使把变量粗略离散化，组合数量也会迅速膨胀，而多数格子可能永远没有被访","frontmatter":{"title":"一张 Q 表装不下真实世界：函数逼近怎样让强化学习学会泛化","description":"表格型强化学习有一个隐含前提：每个状态或状态—动作对都能被列出来，并拥有独立的存储位置。这个前提在小型网格世界里成立，到了自动驾驶却立即失效。车速、横向误差、道路曲率和相对距离都是连续量，同一场景还会随交通参与者数量不断改变维度。即使把变量粗略离散化，组合数量也会迅速膨胀，而多数格子可能永远没有被访","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":14,"source":"2026-08-13/rl_series_10_function_approximation.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_10_table_to_function.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-10-function-approximation"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一张 Q 表装不下真实世界：函数逼近怎样让强化学习学会泛化"}],["meta",{"property":"og:description","content":"表格型强化学习有一个隐含前提：每个状态或状态—动作对都能被列出来，并拥有独立的存储位置。这个前提在小型网格世界里成立，到了自动驾驶却立即失效。车速、横向误差、道路曲率和相对距离都是连续量，同一场景还会随交通参与者数量不断改变维度。即使把变量粗略离散化，组合数量也会迅速膨胀，而多数格子可能永远没有被访"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-10-function-approximation"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_10_table_to_function.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"一张 Q 表装不下真实世界：函数逼近怎样让强化学习学会泛化"}],["meta",{"name":"twitter:description","content":"表格型强化学习有一个隐含前提：每个状态或状态—动作对都能被列出来，并拥有独立的存储位置。这个前提在小型网格世界里成立，到了自动驾驶却立即失效。车速、横向误差、道路曲率和相对距离都是连续量，同一场景还会随交通参与者数量不断改变维度。即使把变量粗略离散化，组合数量也会迅速膨胀，而多数格子可能永远没有被访"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_10_table_to_function.png"}]],"prev":{"text":"奖励隔了十步才出现，前面的动作怎么分功？n 步 TD 与资格迹讲透了","link":"/rl/rl-series-09-n-step-td-eligibility-traces"},"next":{"text":"把 Q 表换成神经网络就够了吗？DQN 的完整训练闭环","link":"/rl/rl-series-11-dqn-foundations"}},"headers":[],"relativePath":"rl/rl-series-10-function-approximation.md","filePath":"rl/rl-series-10-function-approximation.md","lastUpdated":null}'),d={name:"rl/rl-series-10-function-approximation.md"};function p(c,a,_,b,u,m){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="一张-q-表装不下真实世界-函数逼近怎样让强化学习学会泛化" tabindex="-1">一张 Q 表装不下真实世界：函数逼近怎样让强化学习学会泛化 <a class="header-anchor" href="#一张-q-表装不下真实世界-函数逼近怎样让强化学习学会泛化" aria-label="Permalink to &quot;一张 Q 表装不下真实世界：函数逼近怎样让强化学习学会泛化&quot;">​</a></h1><p>表格型强化学习有一个隐含前提：每个状态或状态—动作对都能被列出来，并拥有独立的存储位置。这个前提在小型网格世界里成立，到了自动驾驶却立即失效。车速、横向误差、道路曲率和相对距离都是连续量，同一场景还会随交通参与者数量不断改变维度。即使把变量粗略离散化，组合数量也会迅速膨胀，而多数格子可能永远没有被访问。</p><p>Function Approximation（函数逼近）不再为每个状态保存独立答案，而是用带参数的函数近似价值。一次样本更新参数后，一批具有相似特征的状态都会改变估计。这种 Generalization（泛化）正是从表格方法走向深度强化学习的桥梁，也带来新的风险：共享参数既能传播经验，也可能让新经验破坏旧判断。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-函数逼近改变的是价值的表示方式" tabindex="-1">1.1 函数逼近改变的是价值的表示方式 <a class="header-anchor" href="#_1-1-函数逼近改变的是价值的表示方式" aria-label="Permalink to &quot;1.1 函数逼近改变的是价值的表示方式&quot;">​</a></h3><p>表格方法写作 (V(s)) 或 (Q(s,a))，函数逼近写作 (hat v(s,\\mathbf w)) 或 (hat q(s,a,\\mathbf w))。参数向量 (\\mathbf w) 代替巨大表格，算法仍然可以使用蒙特卡洛回报、时序差分目标和策略改进。</p><h3 id="_1-2-泛化既是收益也是干扰来源" tabindex="-1">1.2 泛化既是收益也是干扰来源 <a class="header-anchor" href="#_1-2-泛化既是收益也是干扰来源" aria-label="Permalink to &quot;1.2 泛化既是收益也是干扰来源&quot;">​</a></h3><p>相似状态共享参数后，未见状态能从已见样本获得估计；但某个状态的梯度更新也会改变其他状态。模型结构和特征决定哪些状态被视为相似，错误的相似性会系统性传播误差。</p><h3 id="_1-3-线性方法是最清楚的起点" tabindex="-1">1.3 线性方法是最清楚的起点 <a class="header-anchor" href="#_1-3-线性方法是最清楚的起点" aria-label="Permalink to &quot;1.3 线性方法是最清楚的起点&quot;">​</a></h3><p>线性价值函数把状态特征与权重做内积，表达能力有限，却能清楚展示特征、目标、梯度和更新之间的关系。神经网络只是更复杂的函数逼近器，不是函数逼近的定义本身。</p><h3 id="_1-4-函数逼近不自动解决连续动作" tabindex="-1">1.4 函数逼近不自动解决连续动作 <a class="header-anchor" href="#_1-4-函数逼近不自动解决连续动作" aria-label="Permalink to &quot;1.4 函数逼近不自动解决连续动作&quot;">​</a></h3><p>网络可以接收连续状态，但若控制仍通过 (\\arg\\max_a \\hat q(s,a)) 穷举动作，动作集合通常必须离散且规模可控。连续转角、加速度的优化还需要策略梯度或 Actor-Critic（演员—评论家）等后续方法。</p><p><img src="'+h+'" alt="表格表示与函数逼近的根本区别"></p><h2 id="二、为什么一张表会迅速失效" tabindex="-1">二、为什么一张表会迅速失效 <a class="header-anchor" href="#二、为什么一张表会迅速失效" aria-label="Permalink to &quot;二、为什么一张表会迅速失效&quot;">​</a></h2><h3 id="_2-1-连续变量没有有限格子" tabindex="-1">2.1 连续变量没有有限格子 <a class="header-anchor" href="#_2-1-连续变量没有有限格子" aria-label="Permalink to &quot;2.1 连续变量没有有限格子&quot;">​</a></h3><p>车速从每小时 60 公里变到 60.01 公里，物理状态发生变化；横向误差和航向误差也可以取任意实数。若把每个实数当成独立状态，表格需要无限多行。</p><h3 id="_2-2-离散化只能推迟维度灾难" tabindex="-1">2.2 离散化只能推迟维度灾难 <a class="header-anchor" href="#_2-2-离散化只能推迟维度灾难" aria-label="Permalink to &quot;2.2 离散化只能推迟维度灾难&quot;">​</a></h3><p>假设十个状态变量各切成一百档，组合数就是 (100^{10})。继续加入周车距离、相对速度、信号灯相位和道路曲率，状态数按乘法增长。更粗分箱会减小表格，却会把驾驶含义不同的状态压进同一格。</p><h3 id="_2-3-独立格子不会共享经验" tabindex="-1">2.3 独立格子不会共享经验 <a class="header-anchor" href="#_2-3-独立格子不会共享经验" aria-label="Permalink to &quot;2.3 独立格子不会共享经验&quot;">​</a></h3><p>表格中 60 公里时速学到的制动价值，不会自动帮助 60.01 公里时速。相邻状态在物理上几乎相同，存储上却彼此隔离，数据利用率因而很低。</p><h2 id="三、参数化价值函数怎样压缩状态空间" tabindex="-1">三、参数化价值函数怎样压缩状态空间 <a class="header-anchor" href="#三、参数化价值函数怎样压缩状态空间" aria-label="Permalink to &quot;三、参数化价值函数怎样压缩状态空间&quot;">​</a></h2><h3 id="_3-1-从查表变成计算" tabindex="-1">3.1 从查表变成计算 <a class="header-anchor" href="#_3-1-从查表变成计算" aria-label="Permalink to &quot;3.1 从查表变成计算&quot;">​</a></h3><p>函数逼近器接收状态表示，经过一组共享参数输出价值：</p><p>$$ \\hat v(s,\\mathbf w)\\approx v_\\pi(s) $$</p><p>预测时不再寻找唯一格子，而是执行一次函数计算。模型容量由参数数量决定，不再与可枚举状态数一一对应。</p><h3 id="_3-2-压缩意味着必须作出相似性假设" tabindex="-1">3.2 压缩意味着必须作出相似性假设 <a class="header-anchor" href="#_3-2-压缩意味着必须作出相似性假设" aria-label="Permalink to &quot;3.2 压缩意味着必须作出相似性假设&quot;">​</a></h3><p>有限参数不可能为无限状态保存完全独立的答案。模型必须假设某些状态具有共享结构，例如车速接近、曲率相似且安全裕度相近的状态，其长期回报也可能接近。</p><h3 id="_3-3-参数少不等于信息无损" tabindex="-1">3.3 参数少不等于信息无损 <a class="header-anchor" href="#_3-3-参数少不等于信息无损" aria-label="Permalink to &quot;3.3 参数少不等于信息无损&quot;">​</a></h3><p>函数逼近是一种有偏压缩。若特征遗漏前车急减速趋势，模型再复杂也无法仅凭当前距离恢复这部分信息。表示能力、可观测性和训练数据共同限制最终精度。</p><h2 id="四、线性价值函数如何工作" tabindex="-1">四、线性价值函数如何工作 <a class="header-anchor" href="#四、线性价值函数如何工作" aria-label="Permalink to &quot;四、线性价值函数如何工作&quot;">​</a></h2><h3 id="_4-1-状态先变成特征向量" tabindex="-1">4.1 状态先变成特征向量 <a class="header-anchor" href="#_4-1-状态先变成特征向量" aria-label="Permalink to &quot;4.1 状态先变成特征向量&quot;">​</a></h3><p>用 (\\mathbf x(s)=[x_1(s),x_2(s),\\ldots,x_d(s)]^\\top) 表示状态特征，例如归一化车速、横向误差、航向误差、曲率和安全裕度。</p><h3 id="_4-2-价值是特征的加权和" tabindex="-1">4.2 价值是特征的加权和 <a class="header-anchor" href="#_4-2-价值是特征的加权和" aria-label="Permalink to &quot;4.2 价值是特征的加权和&quot;">​</a></h3><p>线性近似写作：</p><p>$$ \\hat v(s,\\mathbf w)=\\mathbf w^\\top\\mathbf x(s) $$</p><p>每个权重表达对应特征对价值预测的线性贡献。加入常数特征可以学习截距，加入交叉项则能表示部分变量之间的相互作用。</p><h3 id="_4-3-梯度就是特征本身" tabindex="-1">4.3 梯度就是特征本身 <a class="header-anchor" href="#_4-3-梯度就是特征本身" aria-label="Permalink to &quot;4.3 梯度就是特征本身&quot;">​</a></h3><p>线性模型满足：</p><p>$$ \\nabla_{\\mathbf w}\\hat v(s,\\mathbf w)=\\mathbf x(s) $$</p><p>因此样本误差会沿当前特征方向更新参数。这条简单关系使线性方法特别适合检查尺度、方向和数值稳定性。</p><p><img src="'+o+'" alt="线性价值函数把状态特征压缩为一个价值估计"></p><h2 id="五、特征决定了模型眼中的世界" tabindex="-1">五、特征决定了模型眼中的世界 <a class="header-anchor" href="#五、特征决定了模型眼中的世界" aria-label="Permalink to &quot;五、特征决定了模型眼中的世界&quot;">​</a></h2><h3 id="_5-1-原始变量不一定适合直接输入" tabindex="-1">5.1 原始变量不一定适合直接输入 <a class="header-anchor" href="#_5-1-原始变量不一定适合直接输入" aria-label="Permalink to &quot;5.1 原始变量不一定适合直接输入&quot;">​</a></h3><p>车速范围可能是几十，横向误差可能小于一，碰撞指示只有零和一。若不做尺度处理，较大数值特征可能主导梯度，学习率也更难统一选择。</p><h3 id="_5-2-归一化改善数值条件" tabindex="-1">5.2 归一化改善数值条件 <a class="header-anchor" href="#_5-2-归一化改善数值条件" aria-label="Permalink to &quot;5.2 归一化改善数值条件&quot;">​</a></h3><p>常见做法是依据物理范围缩放到相近区间，或使用训练数据统计量标准化。统计量必须只由训练数据估计，并在评估阶段固定，否则会产生数据泄漏和部署漂移。</p><h3 id="_5-3-基函数可以表达局部结构" tabindex="-1">5.3 基函数可以表达局部结构 <a class="header-anchor" href="#_5-3-基函数可以表达局部结构" aria-label="Permalink to &quot;5.3 基函数可以表达局部结构&quot;">​</a></h3><p>Tile Coding（瓦片编码）、Radial Basis Function（径向基函数）和 Fourier Basis（傅里叶基函数）都能把连续状态映射为更丰富的特征。它们仍可配合线性权重，却能表达分段、局部或周期结构。</p><h3 id="_5-4-特征工程也会注入偏见" tabindex="-1">5.4 特征工程也会注入偏见 <a class="header-anchor" href="#_5-4-特征工程也会注入偏见" aria-label="Permalink to &quot;5.4 特征工程也会注入偏见&quot;">​</a></h3><p>把左右横向误差直接取绝对值，会丢掉方向；只保留最近车辆距离，可能丢掉目标车道后车威胁。特征设计不是无害预处理，而是在定义模型可以区分什么。</p><h2 id="六、预测目标从哪里来" tabindex="-1">六、预测目标从哪里来 <a class="header-anchor" href="#六、预测目标从哪里来" aria-label="Permalink to &quot;六、预测目标从哪里来&quot;">​</a></h2><h3 id="_6-1-监督信号不是人工标签" tabindex="-1">6.1 监督信号不是人工标签 <a class="header-anchor" href="#_6-1-监督信号不是人工标签" aria-label="Permalink to &quot;6.1 监督信号不是人工标签&quot;">​</a></h3><p>价值函数的目标来自交互轨迹。蒙特卡洛方法使用完整回报 (G_t)，时序差分方法使用奖励和下一状态估计组成的自举目标。</p><h3 id="_6-2-状态分布决定优化重点" tabindex="-1">6.2 状态分布决定优化重点 <a class="header-anchor" href="#_6-2-状态分布决定优化重点" aria-label="Permalink to &quot;6.2 状态分布决定优化重点&quot;">​</a></h3><p>常见平方误差目标可写为：</p><p>$$ J(\\mathbf w)=\\mathbb E_{S\\sim\\mu}\\left[\\left(v_\\pi(S)-\\hat v(S,\\mathbf w)\\right)^2\\right] $$</p><p>其中 (\\mu) 是状态采样分布。模型会优先拟合频繁出现的状态，而不是自动对所有可能状态同样准确。</p><h3 id="_6-3-数据覆盖比平均损失更重要" tabindex="-1">6.3 数据覆盖比平均损失更重要 <a class="header-anchor" href="#_6-3-数据覆盖比平均损失更重要" aria-label="Permalink to &quot;6.3 数据覆盖比平均损失更重要&quot;">​</a></h3><p>高速急弯可能很少出现，却具有更高安全风险。若训练分布几乎不含这些状态，即使总体误差很低，也不能说明关键边界可靠。应单独报告危险子集和分布外场景。</p><h2 id="七、蒙特卡洛目标怎样更新参数" tabindex="-1">七、蒙特卡洛目标怎样更新参数 <a class="header-anchor" href="#七、蒙特卡洛目标怎样更新参数" aria-label="Permalink to &quot;七、蒙特卡洛目标怎样更新参数&quot;">​</a></h2><h3 id="_7-1-把完整回报当作回归标签" tabindex="-1">7.1 把完整回报当作回归标签 <a class="header-anchor" href="#_7-1-把完整回报当作回归标签" aria-label="Permalink to &quot;7.1 把完整回报当作回归标签&quot;">​</a></h3><p>给定样本 ((S_t,G_t))，误差为 (G_t-\\hat v(S_t,\\mathbf w_t))。随机梯度更新写作：</p><p>$$ \\mathbf w_{t+1}=\\mathbf w_t+\\alpha\\left[G_t-\\hat v(S_t,\\mathbf w_t)\\right]\\nabla_{\\mathbf w}\\hat v(S_t,\\mathbf w_t) $$</p><h3 id="_7-2-线性模型更新尤其直观" tabindex="-1">7.2 线性模型更新尤其直观 <a class="header-anchor" href="#_7-2-线性模型更新尤其直观" aria-label="Permalink to &quot;7.2 线性模型更新尤其直观&quot;">​</a></h3><p>代入梯度后，误差乘以当前特征再写入权重。某个特征为零，对应权重不更新；特征绝对值越大，同一误差产生的参数变化越大。</p><h3 id="_7-3-完整回报仍有高方差" tabindex="-1">7.3 完整回报仍有高方差 <a class="header-anchor" href="#_7-3-完整回报仍有高方差" aria-label="Permalink to &quot;7.3 完整回报仍有高方差&quot;">​</a></h3><p>函数逼近减少存储量，却不会消除蒙特卡洛回报受长轨迹随机性影响的问题。模型、目标和采样是三个不同维度，换模型不等于换掉目标的统计性质。</p><h2 id="八、半梯度-td-为什么叫-半梯度" tabindex="-1">八、半梯度 TD 为什么叫“半梯度” <a class="header-anchor" href="#八、半梯度-td-为什么叫-半梯度" aria-label="Permalink to &quot;八、半梯度 TD 为什么叫“半梯度”&quot;">​</a></h2><h3 id="_8-1-一步目标包含当前估计" tabindex="-1">8.1 一步目标包含当前估计 <a class="header-anchor" href="#_8-1-一步目标包含当前估计" aria-label="Permalink to &quot;8.1 一步目标包含当前估计&quot;">​</a></h3><p>状态价值 TD 目标为：</p><p>$$ Y_t=R_{t+1}+\\gamma\\hat v(S_{t+1},\\mathbf w_t) $$</p><p>更新使用 (Y_t-\\hat v(S_t,\\mathbf w_t)) 作为 Temporal-Difference Error（时序差分误差）。</p><h3 id="_8-2-更新时把目标暂时视为常数" tabindex="-1">8.2 更新时把目标暂时视为常数 <a class="header-anchor" href="#_8-2-更新时把目标暂时视为常数" aria-label="Permalink to &quot;8.2 更新时把目标暂时视为常数&quot;">​</a></h3><p>虽然目标中的下一状态价值也依赖参数，Semi-Gradient TD（半梯度时序差分）只对当前状态预测求梯度：</p><p>$$ \\mathbf w_{t+1}=\\mathbf w_t+\\alpha\\left[Y_t-\\hat v(S_t,\\mathbf w_t)\\right]\\nabla_{\\mathbf w}\\hat v(S_t,\\mathbf w_t) $$</p><p>“半”指忽略目标对参数的导数，不代表只更新一半参数。</p><h3 id="_8-3-自举目标会随训练移动" tabindex="-1">8.3 自举目标会随训练移动 <a class="header-anchor" href="#_8-3-自举目标会随训练移动" aria-label="Permalink to &quot;8.3 自举目标会随训练移动&quot;">​</a></h3><p>参数改变后，当前预测和下一状态目标都可能变化。因此这不是固定标签的普通监督学习，学习率、数据分布和更新方式对稳定性更加敏感。</p><p><img src="'+l+'" alt="蒙特卡洛与半梯度 TD 使用不同目标更新共享参数"></p><h2 id="九、动作价值函数怎样用于控制" tabindex="-1">九、动作价值函数怎样用于控制 <a class="header-anchor" href="#九、动作价值函数怎样用于控制" aria-label="Permalink to &quot;九、动作价值函数怎样用于控制&quot;">​</a></h2><h3 id="_9-1-线性动作价值可以共享状态特征" tabindex="-1">9.1 线性动作价值可以共享状态特征 <a class="header-anchor" href="#_9-1-线性动作价值可以共享状态特征" aria-label="Permalink to &quot;9.1 线性动作价值可以共享状态特征&quot;">​</a></h3><p>一种做法为每个离散动作维护一组权重，写作 (\\hat q(s,a,\\mathbf w))。也可以把状态与动作共同编码成特征 (\\mathbf x(s,a))，再计算内积。</p><h3 id="_9-2-策略改进仍依赖动作比较" tabindex="-1">9.2 策略改进仍依赖动作比较 <a class="header-anchor" href="#_9-2-策略改进仍依赖动作比较" aria-label="Permalink to &quot;9.2 策略改进仍依赖动作比较&quot;">​</a></h3><p>离散动作下可以选择：</p><p>$$ A_t=\\arg\\max_a\\hat q(S_t,a,\\mathbf w) $$</p><p>训练时通常保留 ε-greedy（ε-贪心）探索。函数逼近能估计未见状态，不代表未尝试动作的数据缺口已经消失。</p><h3 id="_9-3-控制比固定策略预测更危险" tabindex="-1">9.3 控制比固定策略预测更危险 <a class="header-anchor" href="#_9-3-控制比固定策略预测更危险" aria-label="Permalink to &quot;9.3 控制比固定策略预测更危险&quot;">​</a></h3><p>策略会根据估计值改变采样分布，而新数据又继续修改估计。预测问题中的固定数据目标，变成模型、策略与数据分布互相追逐的闭环。</p><h2 id="十、泛化为什么能提高样本效率" tabindex="-1">十、泛化为什么能提高样本效率 <a class="header-anchor" href="#十、泛化为什么能提高样本效率" aria-label="Permalink to &quot;十、泛化为什么能提高样本效率&quot;">​</a></h2><h3 id="_10-1-一次经验可影响邻近状态" tabindex="-1">10.1 一次经验可影响邻近状态 <a class="header-anchor" href="#_10-1-一次经验可影响邻近状态" aria-label="Permalink to &quot;10.1 一次经验可影响邻近状态&quot;">​</a></h3><p>若两个状态激活相似特征，一次更新会同时改变它们的预测。模型因此能在未逐格访问的情况下形成平滑价值地形。</p><h3 id="_10-2-参数共享可以提取重复结构" tabindex="-1">10.2 参数共享可以提取重复结构 <a class="header-anchor" href="#_10-2-参数共享可以提取重复结构" aria-label="Permalink to &quot;10.2 参数共享可以提取重复结构&quot;">​</a></h3><p>不同道路片段可能共享“安全裕度变小会降低价值”这一规律。函数逼近把局部轨迹压缩为可复用模式，避免每条道路都从零学习。</p><h3 id="_10-3-泛化范围由表示决定" tabindex="-1">10.3 泛化范围由表示决定 <a class="header-anchor" href="#_10-3-泛化范围由表示决定" aria-label="Permalink to &quot;10.3 泛化范围由表示决定&quot;">​</a></h3><p>线性特征、局部基函数与深度网络产生的相似性不同。不能只说模型“会泛化”，还应通过邻域扰动、未见组合和跨场景评估确认它泛化到了哪里。</p><h2 id="十一、干扰为什么是泛化的另一面" tabindex="-1">十一、干扰为什么是泛化的另一面 <a class="header-anchor" href="#十一、干扰为什么是泛化的另一面" aria-label="Permalink to &quot;十一、干扰为什么是泛化的另一面&quot;">​</a></h2><h3 id="_11-1-共享参数让价值相互耦合" tabindex="-1">11.1 共享参数让价值相互耦合 <a class="header-anchor" href="#_11-1-共享参数让价值相互耦合" aria-label="Permalink to &quot;11.1 共享参数让价值相互耦合&quot;">​</a></h3><p>同一权重被多个状态使用，优化状态 A 时可能改善状态 B，也可能破坏状态 C。表格方法局部写入，函数逼近则产生非局部影响。</p><h3 id="_11-2-新数据可能覆盖旧能力" tabindex="-1">11.2 新数据可能覆盖旧能力 <a class="header-anchor" href="#_11-2-新数据可能覆盖旧能力" aria-label="Permalink to &quot;11.2 新数据可能覆盖旧能力&quot;">​</a></h3><p>若训练后期数据集中在某类弯道，参数可能更适合该分布，却降低直道或另一速度区间的性能。这类 Catastrophic Interference（灾难性干扰）需要通过回放、多场景采样和分组评估发现。</p><h3 id="_11-3-平均回报会掩盖局部退化" tabindex="-1">11.3 平均回报会掩盖局部退化 <a class="header-anchor" href="#_11-3-平均回报会掩盖局部退化" aria-label="Permalink to &quot;11.3 平均回报会掩盖局部退化&quot;">​</a></h3><p>整体回报上升时，少数安全关键状态仍可能明显变差。训练曲线之外，应固定一组覆盖典型与边界场景的评估集，持续观察分项指标。</p><p><img src="'+n+'" alt="泛化与干扰来自同一套参数共享机制"></p><h2 id="十二、-致命三角-在警告什么" tabindex="-1">十二、“致命三角”在警告什么 <a class="header-anchor" href="#十二、-致命三角-在警告什么" aria-label="Permalink to &quot;十二、“致命三角”在警告什么&quot;">​</a></h2><h3 id="_12-1-三个因素组合会带来不稳定风险" tabindex="-1">12.1 三个因素组合会带来不稳定风险 <a class="header-anchor" href="#_12-1-三个因素组合会带来不稳定风险" aria-label="Permalink to &quot;12.1 三个因素组合会带来不稳定风险&quot;">​</a></h3><p>Function Approximation（函数逼近）、Bootstrapping（自举）与 Off-Policy Learning（异策略学习）同时出现时，某些算法可能发散。这一组合通常称为 Deadly Triad（致命三角）。</p><h3 id="_12-2-单个因素不是原罪" tabindex="-1">12.2 单个因素不是原罪 <a class="header-anchor" href="#_12-2-单个因素不是原罪" aria-label="Permalink to &quot;12.2 单个因素不是原罪&quot;">​</a></h3><p>线性同策略半梯度 TD 在合适条件下有良好理论性质；自举也是高效学习的重要来源。警告针对特定组合和假设破坏，不能简化为“用了神经网络就一定发散”。</p><h3 id="_12-3-深度强化学习仍在管理这个矛盾" tabindex="-1">12.3 深度强化学习仍在管理这个矛盾 <a class="header-anchor" href="#_12-3-深度强化学习仍在管理这个矛盾" aria-label="Permalink to &quot;12.3 深度强化学习仍在管理这个矛盾&quot;">​</a></h3><p>DQN 使用经验回放、目标网络和裁剪等工程手段改善稳定性，但不意味着风险从理论上消失。训练能跑完也不等于价值估计可信。</p><h2 id="十三、连续动作为什么仍是边界" tabindex="-1">十三、连续动作为什么仍是边界 <a class="header-anchor" href="#十三、连续动作为什么仍是边界" aria-label="Permalink to &quot;十三、连续动作为什么仍是边界&quot;">​</a></h2><h3 id="_13-1-输入连续不等于输出可优化" tabindex="-1">13.1 输入连续不等于输出可优化 <a class="header-anchor" href="#_13-1-输入连续不等于输出可优化" aria-label="Permalink to &quot;13.1 输入连续不等于输出可优化&quot;">​</a></h3><p>网络很容易接收连续状态；若动作也连续，求 (\\arg\\max_a\\hat q(s,a)) 就成为每个控制周期内的非线性优化问题。</p><h3 id="_13-2-粗离散动作会引入控制误差" tabindex="-1">13.2 粗离散动作会引入控制误差 <a class="header-anchor" href="#_13-2-粗离散动作会引入控制误差" aria-label="Permalink to &quot;13.2 粗离散动作会引入控制误差&quot;">​</a></h3><p>把方向盘角度切成左、中、右便于穷举，却可能造成振荡和低分辨率控制。继续增加动作档位又会扩大输出维度与探索成本。</p><h3 id="_13-3-应根据问题选择算法族" tabindex="-1">13.3 应根据问题选择算法族 <a class="header-anchor" href="#_13-3-应根据问题选择算法族" aria-label="Permalink to &quot;13.3 应根据问题选择算法族&quot;">​</a></h3><p>离散高层决策可以使用 DQN；连续低层控制更常使用显式策略网络。不要因为价值函数能接收动作向量，就假定最大化操作已经有可实时执行的答案。</p><h2 id="十四、自动驾驶特征应怎样组织" tabindex="-1">十四、自动驾驶特征应怎样组织 <a class="header-anchor" href="#十四、自动驾驶特征应怎样组织" aria-label="Permalink to &quot;十四、自动驾驶特征应怎样组织&quot;">​</a></h2><h3 id="_14-1-先区分任务层级" tabindex="-1">14.1 先区分任务层级 <a class="header-anchor" href="#_14-1-先区分任务层级" aria-label="Permalink to &quot;14.1 先区分任务层级&quot;">​</a></h3><p>换道决策可用车道占用、相对距离与相对速度；横向控制还需要横向误差、航向误差、曲率和执行器状态。不同层级不应共享一套含义模糊的“大状态”。</p><h3 id="_14-2-保留物理方向和时间信息" tabindex="-1">14.2 保留物理方向和时间信息 <a class="header-anchor" href="#_14-2-保留物理方向和时间信息" aria-label="Permalink to &quot;14.2 保留物理方向和时间信息&quot;">​</a></h3><p>特征应区分左右、接近与远离，并在观测不足时加入历史窗口或状态估计。只有瞬时距离而没有相对速度，通常无法满足对未来碰撞趋势的判断。</p><h3 id="_14-3-安全约束不能只靠价值惩罚" tabindex="-1">14.3 安全约束不能只靠价值惩罚 <a class="header-anchor" href="#_14-3-安全约束不能只靠价值惩罚" aria-label="Permalink to &quot;14.3 安全约束不能只靠价值惩罚&quot;">​</a></h3><p>碰撞大惩罚属于训练信号，不是运行时保证。部署仍需独立约束、Safety Shield（安全屏蔽）、Control Barrier Function（控制屏障函数）或经过验证的后备控制器。</p><p><img src="'+s+'" alt="自动驾驶价值逼近需要任务化特征与独立安全边界"></p><h2 id="十五、一个最小实验应该怎么做" tabindex="-1">十五、一个最小实验应该怎么做 <a class="header-anchor" href="#十五、一个最小实验应该怎么做" aria-label="Permalink to &quot;十五、一个最小实验应该怎么做&quot;">​</a></h2><h3 id="_15-1-从固定策略预测开始" tabindex="-1">15.1 从固定策略预测开始 <a class="header-anchor" href="#_15-1-从固定策略预测开始" aria-label="Permalink to &quot;15.1 从固定策略预测开始&quot;">​</a></h3><p>先选可复现的小环境与固定策略，对比粗分箱表格、线性特征和局部基函数。固定采样预算，报告训练分布内误差与未见状态误差。</p><h3 id="_15-2-再比较蒙特卡洛与半梯度-td" tabindex="-1">15.2 再比较蒙特卡洛与半梯度 TD <a class="header-anchor" href="#_15-2-再比较蒙特卡洛与半梯度-td" aria-label="Permalink to &quot;15.2 再比较蒙特卡洛与半梯度 TD&quot;">​</a></h3><p>保持模型和数据一致，只替换学习目标，观察收敛速度、方差和对学习率的敏感性。这样才能把目标差异与模型差异分开。</p><h3 id="_15-3-最后进入控制闭环" tabindex="-1">15.3 最后进入控制闭环 <a class="header-anchor" href="#_15-3-最后进入控制闭环" aria-label="Permalink to &quot;15.3 最后进入控制闭环&quot;">​</a></h3><p>加入 ε-贪心策略改进后，额外记录状态覆盖、动作覆盖、回报、安全事件和价值范围。若结果恶化，先确认是表示、采样还是自举稳定性问题。</p><h2 id="十六、最常见的理解错误" tabindex="-1">十六、最常见的理解错误 <a class="header-anchor" href="#十六、最常见的理解错误" aria-label="Permalink to &quot;十六、最常见的理解错误&quot;">​</a></h2><h3 id="_16-1-把函数逼近等同于深度网络" tabindex="-1">16.1 把函数逼近等同于深度网络 <a class="header-anchor" href="#_16-1-把函数逼近等同于深度网络" aria-label="Permalink to &quot;16.1 把函数逼近等同于深度网络&quot;">​</a></h3><p>线性模型、决策树、核方法和神经网络都可做函数逼近。深度只是模型族，不改变价值目标来自强化学习轨迹这一事实。</p><h3 id="_16-2-只看训练损失判断策略好坏" tabindex="-1">16.2 只看训练损失判断策略好坏 <a class="header-anchor" href="#_16-2-只看训练损失判断策略好坏" aria-label="Permalink to &quot;16.2 只看训练损失判断策略好坏&quot;">​</a></h3><p>较低 TD 损失可能只是更好拟合当前回放分布，不保证贪心策略回报更高，更不保证分布外安全。</p><h3 id="_16-3-忽略状态采样分布" tabindex="-1">16.3 忽略状态采样分布 <a class="header-anchor" href="#_16-3-忽略状态采样分布" aria-label="Permalink to &quot;16.3 忽略状态采样分布&quot;">​</a></h3><p>模型对哪里准确由数据决定。若只报告全局均值而不报告关键区域覆盖，结果无法支持自动驾驶结论。</p><h3 id="_16-4-认为泛化一定平滑且正确" tabindex="-1">16.4 认为泛化一定平滑且正确 <a class="header-anchor" href="#_16-4-认为泛化一定平滑且正确" aria-label="Permalink to &quot;16.4 认为泛化一定平滑且正确&quot;">​</a></h3><p>神经网络可在局部产生突变，线性模型也可能因特征尺度错误给出异常外推。必须通过扰动测试与范围检查观察函数形状。</p><h2 id="十七、学到什么程度才算真正掌握" tabindex="-1">十七、学到什么程度才算真正掌握 <a class="header-anchor" href="#十七、学到什么程度才算真正掌握" aria-label="Permalink to &quot;十七、学到什么程度才算真正掌握&quot;">​</a></h2><h3 id="_17-1-能从目标写出更新式" tabindex="-1">17.1 能从目标写出更新式 <a class="header-anchor" href="#_17-1-能从目标写出更新式" aria-label="Permalink to &quot;17.1 能从目标写出更新式&quot;">​</a></h3><p>看到蒙特卡洛回报或 TD 目标，应能写出误差、梯度方向和线性模型的参数更新，并解释半梯度忽略了哪部分导数。</p><h3 id="_17-2-能解释一次更新影响哪些状态" tabindex="-1">17.2 能解释一次更新影响哪些状态 <a class="header-anchor" href="#_17-2-能解释一次更新影响哪些状态" aria-label="Permalink to &quot;17.2 能解释一次更新影响哪些状态&quot;">​</a></h3><p>掌握的标志不是背公式，而是能根据特征激活说明参数共享范围，以及为什么相邻状态会受益或被干扰。</p><h3 id="_17-3-能指出算法适用边界" tabindex="-1">17.3 能指出算法适用边界 <a class="header-anchor" href="#_17-3-能指出算法适用边界" aria-label="Permalink to &quot;17.3 能指出算法适用边界&quot;">​</a></h3><p>需要明确连续状态可以输入模型，离散动作才能被普通 DQN 直接穷举；安全关键部署还需要独立验证与约束。</p><h3 id="_17-4-能读懂下一篇的-dqn-结构" tabindex="-1">17.4 能读懂下一篇的 DQN 结构 <a class="header-anchor" href="#_17-4-能读懂下一篇的-dqn-结构" aria-label="Permalink to &quot;17.4 能读懂下一篇的 DQN 结构&quot;">​</a></h3><p>下一篇会把线性动作价值换成深度 Q 网络，并解释为什么仅替换模型还不够，训练还需要 Replay Buffer（回放缓冲区）和 Target Network（目标网络）共同构成闭环。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="http://incompleteideas.net/book/the-book-2nd.html" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction》第二版，第九章与第十一章</a></p><p><a href="https://www.youtube.com/watch?v=UoPei5o4fps" target="_blank" rel="noreferrer">David Silver 强化学习课程第六讲 Value Function Approximation（价值函数逼近）</a></p><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/docs/chapter6/chapter6.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第六章深度 Q 网络</a></p><p><a href="https://www.nature.com/articles/nature14236" target="_blank" rel="noreferrer">DeepMind《Human-level control through deep reinforcement learning》</a></p>',155)])])}const x=e(d,[["render",p]]);export{f as __pageData,x as default};
